    #[test]
    fn feedback_prompt_uses_neutral_framing() {
        // Verify the prompt text is neutral, not negative
        let prompt = Prompt {
            key: "feedback_message".to_string(),
            question: "Describe your feedback:".to_string(),
            prompt_type: PromptType::Input,
